  const bogus = provisional
    .filter((p) => !leaves.some((leaf) => leaf.id === p.id))
    .map((p) => `${p.id} is listed as provisional but is not a leaf in requirements.md`);
  assert.deepEqual(bogus, [], bogus.join('\n  '));

